    moves[1] = DIR_RIGHT;
    moves[2] = DIR_RIGHT; // robe
    moves[3] = DIR_DOWN;
    moves[4] = DIR_DOWN;
    moves[5] = DIR_DOWN;
    moves[6] = DIR_LEFT;
    moves[7] = DIR_LEFT;
    moves[8] = DIR_LEFT; // scepter at (0,3)
    moves[9] = DIR_RIGHT;
